files.template:
{
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "timeout": 20,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook context"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "timeout": 20,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook session-init"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "^Bash$|^mcp__.+__(read|view|cat)(_file|_files)?$|^Grep$|^Glob$|^memory_search$|^memory$|^mcp__.+__memory_search$",
        "hooks": [
          {
            "type": "command",
            "timeout": 30,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook file-context"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "timeout": 5,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook observation"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "timeout": 60,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook summarize"
          }
        ]
      }
    ],
    "PostCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "timeout": 20,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook post-compact"
          }
        ]
      }
    ],
    "SubagentStart": [
      {
        "hooks": [
          {
            "type": "command",
            "timeout": 20,
            "command": "exit 1",
            "commandWindows": "\"@@NODE@@\" \"@@ROOT@@\\codex-local.mjs\" hook subagent-context"
          }
        ]
      }
    ]
  }
}
